import { demand, sum, same, sequence, compensatedAdder } from './offline-kit.js';
import { wholeFloor, wholeCeil, budgetFits } from './resource-rounding.js';

// Treat only floating-point roundoff at an arithmetic equality as zero.
const difference = (a, b) => budgetFits(a,b) && budgetFits(b,a) ? 0 : a-b;

function stockBalances(initial, deliveries, demands) {
  same(deliveries,demands);
  const receipts=compensatedAdder(initial),uses=compensatedAdder();
  return deliveries.map((delivery,i)=>difference(receipts(delivery),uses(demands[i])));
}

function queue(arrivals, services) {
  same(arrivals,services);
  demand(arrivals.every((v,i)=>i===0||v>=arrivals[i-1]), 'Arrivals must be nondecreasing.');
  let time=0;
  return arrivals.map((arrival,i)=>{const start=Math.max(time,arrival);time=start+services[i];return {start,finish:time,wait:difference(start,arrival)};});
}
function dispatch(services, servers) {
  const loads=sequence(servers,()=>0);
  return services.map((duration,i)=>{const server=loads.indexOf(Math.min(...loads)),start=loads[server];loads[server]+=duration;return {job:i+1,server:server+1,start,finish:loads[server]};});
}
function fluid(initial, inflows, withdrawals, capacity) {
  same(inflows,withdrawals);demand(initial<=capacity,'Initial stock exceeds capacity.');let stock=initial;
  return inflows.map((input,i)=>{const spill=Math.max(0,difference(stock+input,capacity)),available=Math.min(capacity,stock+input),shortage=Math.max(0,difference(withdrawals[i],available));stock=Math.max(0,difference(available,withdrawals[i]));return {stock,spill,shortage};});
}
function blendBounds(properties, minimums, maximums) {
  same(properties,minimums,maximums);demand(minimums.every((v,i)=>v<=maximums[i]&&maximums[i]<=1)&&budgetFits(sum(minimums),1)&&budgetFits(1,sum(maximums)),'Invalid or infeasible share bounds.');
  const solve=reverse=>{const shares=[...minimums],order=properties.map((v,i)=>i).sort((i,j)=>(properties[i]-properties[j])*(reverse?-1:1)||i-j);let left=Math.max(0,1-sum(shares));for(const i of order){const extra=Math.min(left,maximums[i]-shares[i]);shares[i]+=extra;left-=extra;}return sum(shares.map((v,i)=>v*properties[i]));};
  return {minimum:solve(false),maximum:solve(true)};
}
function weightCheck(weights, units) {demand(sum(weights)>0,'Weights need a positive total.');demand(units<=1000,'Allocations are limited to 1000 units.');}
function divisor(weights, units, method, prefix=false) {
  weightCheck(weights,units);const grants=weights.map(()=>0),order=[];
  for(let n=0;n<units;n++){const priorities=weights.map((w,i)=>w/(method==='dhondt'?grants[i]+1:method==='imperiali'?grants[i]+2:method==='modified'&&grants[i]===0?1.4:2*grants[i]+1));const i=priorities.indexOf(Math.max(...priorities));grants[i]++;order.push(i+1);}
  return prefix?order:grants;
}
function cappedDivisor(weights,caps,units) {
  weightCheck(weights,units);demand(sum(caps.filter((v,i)=>weights[i]>0))>=units,'Insufficient positive-weight capacity.');const grants=weights.map(()=>0);
  for(let n=0;n<units;n++){const priorities=weights.map((w,i)=>grants[i]<caps[i]?w/(grants[i]+1):-1),i=priorities.indexOf(Math.max(...priorities));grants[i]++;}
  return grants;
}

